import os


class Config:
    """
    Configuration for the Topology-Aware Stacking Ensemble pipeline.
    Defines global constants, file paths, and hyperparameters.
    """

    # ==========================================
    # General Configuration
    # ==========================================
    SEED = 42
    N_FOLDS = 5

    # ==========================================
    # Directories and Paths
    # ==========================================
    # Input metadata paths (generated by the metadata script)
    METADATA_DIR = "./metadata"
    TRAIN_PATH = os.path.join(METADATA_DIR, "train.parquet")
    VAL_PATH = os.path.join(METADATA_DIR, "val.parquet")
    TEST_PATH = os.path.join(METADATA_DIR, "test.parquet")

    # Working directory for caching processed features
    WORKING_DIR = "./working/idea_9"

    # Output submission directory
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # Feature Engineering Parameters
    # ==========================================

    # 1. Lexical View (Text -> Sparse TF-IDF)
    # Using Unigrams and Bigrams, limited to top 3000 features
    LEXICAL_MAX_FEATURES = 3000
    LEXICAL_NGRAM_RANGE = (1, 2)

    # 2. Behavioral View (Subreddits -> Sparse TF-IDF)
    # Treating list of subreddits as a document, Unigrams only
    BEHAVIORAL_MAX_FEATURES = 1000
    BEHAVIORAL_NGRAM_RANGE = (1, 1)

    # 3. Semantic View (Text -> Dense Embeddings)
    # Using a pre-trained SBERT model (frozen)
    SBERT_MODEL_NAME = "all-MiniLM-L6-v2"

    # ==========================================
    # Model Hyperparameters
    # ==========================================

    # Level 1: Lexical Bagger (Random Forest)
    # Optimized for high-dimensional sparse text data
    LEXICAL_RF_PARAMS = {
        "n_estimators": 300,
        "max_depth": None,
        "min_samples_leaf": 2,
        "class_weight": "balanced",
        "n_jobs": -1,
        "random_state": SEED,
        "verbose": 0,
    }

    # Level 1: Behavioral Bagger (Random Forest)
    # Optimized for sparse subreddit history data
    BEHAVIORAL_RF_PARAMS = {
        "n_estimators": 300,
        "max_depth": None,
        "min_samples_leaf": 2,
        "class_weight": "balanced",
        "n_jobs": -1,
        "random_state": SEED,
        "verbose": 0,
    }

    # Level 1: Semantic Booster (XGBoost)
    # Optimized for low-dimensional dense embeddings
    # scale_pos_weight set to ~3.0 based on class imbalance (75% neg / 25% pos)
    SEMANTIC_XGB_PARAMS = {
        "n_estimators": 1000,
        "learning_rate": 0.05,
        "max_depth": 4,
        "subsample": 0.8,
        "colsample_bytree": 0.8,
        "scale_pos_weight": 3.0,
        "objective": "binary:logistic",
        "eval_metric": "auc",
        "n_jobs": -1,
        "random_state": SEED,
        "early_stopping_rounds": 50,
        "verbosity": 0,
    }

    # Level 2: Meta-Learner (Logistic Regression)
    # Calibrates the probabilities from the three Level 1 models
    META_LR_PARAMS = {
        "C": 1.0,
        "penalty": "l2",
        "solver": "lbfgs",
        "random_state": SEED,
        "max_iter": 1000,
    }
